{
  "cvars": {
    "ivs": [
      {
        "description": "Binary indicator for whether the married couple has children (1 = yes, 0 = no). Primary independent variable testing whether having children is associated with fewer extramarital affairs.",
        "columns": [
          "ChildrenBinary"
        ]
      }
    ],
    "dv": {
      "description": "Count of extramarital sexual intercourse events in the past year (0 = none, larger integers = more frequent). Treated as the dependent/count outcome variable.",
      "columns": [
        "affairs"
      ]
    },
    "controls": [
      {
        "description": "Respondent age in years (numeric). Controls for life-course differences in propensity for affairs.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "age"
        ]
      },
      {
        "description": "Number of years married (numeric). Controls for duration of marriage which may influence affairs.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "yearsmarried"
        ]
      },
      {
        "description": "Self-reported religiousness (numeric 1-5). Controls for moral/religious constraints associated with extramarital behavior.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "religiousness"
        ]
      },
      {
        "description": "Education level (numeric code; higher = more education). Controls for socioeconomic / background differences.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "education"
        ]
      },
      {
        "description": "Occupation code (numeric Hollingshead classification). Controls for occupational/social class differences.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "occupation"
        ]
      },
      {
        "description": "Self-rating of marriage happiness (1-5). Controls for marriage quality which likely correlates with affairs.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "rating"
        ]
      },
      {
        "description": "Binary indicator for respondent gender (1 = male, 0 = female). Included both as a control and as a moderator to test whether the effect of children differs by gender.",
        "is_moderator": true,
        "moderator_on": "ChildrenBinary",
        "columns": [
          "gender_male"
        ]
      }
    ]
  },
  "transform_code": "def transform(df: pd.DataFrame) -> pd.DataFrame:\n    \"\"\"\n    Prepares the Fair (Psychology Today) affairs dataset for modeling.\n    - Drops rows with missing values in variables required for the analysis.\n    - Creates a binary ChildrenBinary column (1 = 'yes', 0 = 'no').\n    - Creates a gender_male column (1 = 'male', 0 = 'female').\n    - Ensures numeric columns are numeric and affairs is integer.\n\n    Returns the transformed dataframe containing at minimum the columns used in the model.\n    \"\"\"\n    df = df.copy()\n\n    # Columns needed for analysis\n    required_cols = ['affairs', 'children', 'gender', 'age', 'yearsmarried',\n                     'religiousness', 'education', 'occupation', 'rating']\n\n    # Drop rows missing any required column\n    df = df.dropna(subset=required_cols)\n\n    # Normalize string fields and map to binaries\n    df['ChildrenBinary'] = df['children'].astype(str).str.strip().str.lower().map({'yes': 1, 'no': 0})\n    df['gender_male'] = df['gender'].astype(str).str.strip().str.lower().map({'male': 1, 'female': 0})\n\n    # Remove rows where mapping produced NA (unexpected values)\n    df = df.dropna(subset=['ChildrenBinary', 'gender_male'])\n\n    # Ensure numeric variables are numeric\n    numeric_cols = ['affairs', 'age', 'yearsmarried', 'religiousness', 'education', 'occupation', 'rating']\n    for col in numeric_cols:\n        df[col] = pd.to_numeric(df[col], errors='coerce')\n\n    # Drop any rows with NA introduced by coercion\n    df = df.dropna(subset=numeric_cols)\n\n    # Ensure affairs is a non-negative integer count\n    # (affairs in this dataset are coded as 0,1,2,3,7,12 etc.)\n    df['affairs'] = df['affairs'].astype(int)\n    df.loc[df['affairs'] < 0, 'affairs'] = 0\n\n    # Keep only columns that will be used in modeling (but allow original columns to remain if desired)\n    # Return full df (with added columns) so caller can inspect other fields if needed\n    return df\n",
  "m_code": "def model(df: pd.DataFrame) -> Any:\n    \"\"\"\n    Fits a count regression (Negative Binomial) predicting number of affairs.\n    The model estimates the association of ChildrenBinary with affairs and tests\n    whether this association differs by gender (ChildrenBinary * gender_male interaction).\n\n    Formula:\n      affairs ~ ChildrenBinary * gender_male + age + yearsmarried + religiousness + education + occupation + rating\n\n    Returns the fitted model results object.\n    \"\"\"\n    import statsmodels.formula.api as smf\n    # Ensure the transformed columns exist\n    required = ['affairs', 'ChildrenBinary', 'gender_male', 'age', 'yearsmarried',\n                'religiousness', 'education', 'occupation', 'rating']\n    missing = [c for c in required if c not in df.columns]\n    if len(missing) > 0:\n        raise ValueError(f\"Missing required columns for modeling: {missing}\")\n\n    # Fit Negative Binomial GLM to allow for overdispersion relative to Poisson\n    formula = ('affairs ~ ChildrenBinary * gender_male + age + yearsmarried + '\n               'religiousness + education + occupation + rating')\n\n    nb_model = smf.glm(formula=formula, data=df, family=sm.families.NegativeBinomial()).fit()\n\n    # Return the fitted results object (user can call .summary() or inspect params)\n    return nb_model\n"
}

{
  "cvars": {
    "ivs": [
      {
        "description": "Presence of children in the marriage (binary). Primary independent variable: 1 = there are children in the marriage, 0 = no children.",
        "columns": [
          "Children"
        ]
      }
    ],
    "dv": {
      "description": "Self-reported frequency of extramarital sexual intercourse over the past year (count-like outcome). Higher values indicate more frequent affairs. This is the dependent variable.",
      "columns": [
        "affairs"
      ]
    },
    "controls": [
      {
        "description": "Respondent gender indicator (1 = male, 0 = female). Controls for gender differences in reported affairs.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "Male"
        ]
      },
      {
        "description": "Standardized age (z-score). Controls for age differences in likelihood of affairs.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "Age_z"
        ]
      },
      {
        "description": "Standardized years married (z-score). Controls for marriage duration effects.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "Yearsmarried_z"
        ]
      },
      {
        "description": "Standardized religiousness (z-score). Controls for religiosity which likely influences affairs.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "Religiousness_z"
        ]
      },
      {
        "description": "Standardized education level (z-score). Controls for education differences.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "Education_z"
        ]
      },
      {
        "description": "Standardized occupation index (z-score). Controls for occupational status.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "Occupation_z"
        ]
      },
      {
        "description": "Standardized self-rating of marriage happiness (z-score). Controls for marriage satisfaction which may be associated with affairs.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "Rating_z"
        ]
      }
    ]
  },
  "transform_code": "def transform(df: pd.DataFrame) -> pd.DataFrame:\n    # Work on a copy\n    df = df.copy()\n\n    # Columns required for analysis\n    required = ['affairs', 'children', 'gender', 'age', 'yearsmarried', 'religiousness', 'education', 'occupation', 'rating']\n\n    # Drop rows with missing values in required columns\n    df = df.dropna(subset=required)\n\n    # Encode children: expected values are 'yes'/'no' (factor). Create binary column 'Children'\n    df['Children'] = df['children'].astype(str).str.strip().str.lower().map({'yes': 1, 'no': 0})\n\n    # Encode gender: create Male = 1 if male, 0 if female\n    df['Male'] = df['gender'].astype(str).str.strip().str.lower().map({'male': 1, 'female': 0})\n\n    # If mapping produced NaNs (unexpected levels), drop those rows\n    df = df.dropna(subset=['Children', 'Male'])\n\n    # Ensure numeric columns are numeric\n    numeric_cols = ['age', 'yearsmarried', 'religiousness', 'education', 'occupation', 'rating', 'affairs']\n    for col in numeric_cols:\n        df[col] = pd.to_numeric(df[col], errors='coerce')\n\n    # Drop any rows with newly coerced NaNs in numeric columns\n    df = df.dropna(subset=numeric_cols)\n\n    # Standardize continuous controls to z-scores for interpretability\n    df['Age_z'] = (df['age'] - df['age'].mean()) / df['age'].std(ddof=0)\n    df['Yearsmarried_z'] = (df['yearsmarried'] - df['yearsmarried'].mean()) / df['yearsmarried'].std(ddof=0)\n    df['Religiousness_z'] = (df['religiousness'] - df['religiousness'].mean()) / df['religiousness'].std(ddof=0)\n    df['Education_z'] = (df['education'] - df['education'].mean()) / df['education'].std(ddof=0)\n    df['Occupation_z'] = (df['occupation'] - df['occupation'].mean()) / df['occupation'].std(ddof=0)\n    df['Rating_z'] = (df['rating'] - df['rating'].mean()) / df['rating'].std(ddof=0)\n\n    # Keep only the columns required for modeling (but keep original affairs column as DV)\n    final_cols = ['affairs', 'Children', 'Male', 'Age_z', 'Yearsmarried_z', 'Religiousness_z', 'Education_z', 'Occupation_z', 'Rating_z']\n    df = df[final_cols].reset_index(drop=True)\n\n    return df\n",
  "m_code": "def model(df: pd.DataFrame) -> any:\n    # Model the association between having children and frequency of extramarital affairs,\n    # controlling for demographic and marriage-related covariates.\n    # We use a Zero-Inflated Negative Binomial (ZINB) model because 'affairs' is a nonnegative,\n    # overdispersed count-like variable with many zeros.\n\n    import statsmodels.api as sm\n    from statsmodels.discrete.count_model import ZeroInflatedNegativeBinomialP\n\n    # Ensure a copy\n    df = df.copy()\n\n    # Define model covariates (count model part)\n    exog_vars = ['Children', 'Male', 'Age_z', 'Yearsmarried_z', 'Religiousness_z', 'Education_z', 'Occupation_z', 'Rating_z']\n    exog = sm.add_constant(df[exog_vars], has_constant='add')\n\n    # Endogenous (dependent) variable\n    endog = df['affairs']\n\n    # For the inflation (logit) part, we use a smaller set of covariates that plausibly predict structural zeros\n    # (e.g., presence of children and gender). Include a constant as well.\n    exog_infl = sm.add_constant(df[['Children', 'Male']], has_constant='add')\n\n    # Fit Zero-Inflated Negative Binomial model\n    zinb = ZeroInflatedNegativeBinomialP(endog, exog, exog_infl=exog_infl, inflation='logit')\n\n    # Fit using a robust optimizer; suppress iterative output (disp=0)\n    try:\n        results = zinb.fit(method='bfgs', maxiter=100, disp=0)\n    except Exception:\n        # Fallback to default fit if bfgs fails\n        results = zinb.fit(disp=0)\n\n    # Return the fitted results object (contains parameter estimates, standard errors, summary, etc.)\n    return results\n"
}
